public Page<UserSearchResponseDto> findUserInterestProducts(
        Long userId,
        SortOption sortOption,
        Pageable pageable) {
    log.debug("사용자 관심 상품 목록 조회 시작 - 사용자ID: {}, 페이지: {}, 사이즈: {}",
            userId, pageable.getPageNumber(), pageable.getPageSize());


    QInterest interest = QInterest.interest;
    QInterest interest1 = new QInterest("interest1");
    QUser product = QUser.user;
    QUserColor productColor = QUserColor.userColor;
    QUserSize productSize = QUserSize.userSize;
    QUserImage productImage = QUserImage.userImage;

    try {

        log.debug("관심 상품 데이터 조회 쿼리 실행 - 사용자ID: {}", userId);
        List<Tuple> results = queryFactory.select(
                        interest.id,
                        product.id,
                        product.name,
                        product.englishName,
                        product.releasePrice,
                        productColor.id,
                        productColor.thumbnailImage.imageUrl,
                        productColor.colorName,
                        productSize.purchasePrice.min(),
                        JPAExpressions
                                .select(interest1.count())
                                .from(interest1)
                                .where(interest1.productColor.eq(productColor))
                )
                .from(interest)
                .leftJoin(interest.productColor, productColor)
                .leftJoin(productColor.product, product)
                .leftJoin(productColor.thumbnailImage, productImage)
                .leftJoin(productColor.sizes, productSize)
                .leftJoin(productColor.interests, interest1)
                .where(interest.user.id.eq(userId))
                .groupBy(
                        product.id,
                        productColor.id,
                        productColor.thumbnailImage.imageUrl)
                .orderBy(getOrderByClause(sortOption, product, productColor, productSize))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        log.debug("관심 상품 데이터 조회 완료 - 결과 수: {}", results.size());


        log.debug("관심 상품 전체 개수 조회 시작 - 사용자ID: {}", userId);
        long total = queryFactory.select(interest.count())
                .from(interest)
                .where(interest.user.id.eq(userId))
                .fetchOne();

        log.debug("관심 상품 전체 개수 조회 완료 - 총 개수: {}", total);


        log.debug("관심 상품 데이터 DTO 변환 시작");
        List<UserSearchResponseDto> content = results.stream()
                .map(tuple -> {
                    Long interestCount = tuple.get(JPAExpressions
                            .select(interest1.count())
                            .from(interest1)
                            .where(interest1.productColor.eq(productColor)));

                    return UserSearchResponseDto.builder()
                            .id(tuple.get(product.id))
                            .name(tuple.get(product.name))
                            .englishName(tuple.get(product.englishName))
                            .releasePrice(tuple.get(product.releasePrice))
                            .thumbnailImageUrl(tuple.get(productColor.thumbnailImage.imageUrl))
                            .price(tuple.get(productSize.purchasePrice.min()))
                            .colorName(tuple.get(productColor.colorName))
                            .colorId(tuple.get(productColor.id))
                            .interestCount(interestCount)
                            .build();
                })
                .collect(Collectors.toList());

        log.debug("관심 상품 데이터 DTO 변환 완료 - DTO 수: {}", content.size());

        Page<UserSearchResponseDto> resultPage = new PageImpl<>(content, pageable, total);
        log.debug("사용자 관심 상품 목록 조회 완료 - 총 결과 수: {}, 총 페이지 수: {}",
                resultPage.getTotalElements(), resultPage.getTotalPages());

        return resultPage;
    } catch (Exception e) {
        log.error("사용자 관심 상품 목록 조회 중 예상치 못한 오류 발생 - 사용자ID: {}", userId, e);
    List<Long> productIds = results.stream()
            .map(tuple -> tuple.get(product.id))
            .distinct()
            .toList();







    List<UserSearchResponseDto> content = results.stream()
            .map(tuple -> UserSearchResponseDto.builder()
                    .id(tuple.get(product.id))
                    .name(tuple.get(product.name))
                    .englishName(tuple.get(product.englishName))
                    .releasePrice(tuple.get(product.releasePrice))
                    .thumbnailImageUrl(tuple.get(productColor.thumbnailImage.imageUrl))
                    .colorId(tuple.get(productColor.id))
                    .colorName(tuple.get(productColor.colorName))
                    .price(tuple.get(productSize.purchasePrice.min()))
                    .interestCount(tuple.get(interest.count()))
                    .brandName(tuple.get(product.brand.name))
                    .build())
            .toList();
    System.out.println("content = " + content);


    long total = queryFactory.select(product.id.countDistinct())
            .from(product)
            .leftJoin(product.colors, productColor)
            .leftJoin(productColor.sizes, productSize)
            .where(
                    buildKeywordPredicate(keyword, product, productColor, productSize),
                    buildCategoryPredicate(categoryIds, product),
                    buildGenderPredicate(genders, product),
                    buildBrandPredicate(brandIds, product),
                    buildCollectionPredicate(collectionIds, product),
                    buildColorPredicate(colors, productColor),
                    buildSizePredicate(sizes, productSize),
                    buildPricePredicate(minPrice, maxPrice, productSize)
            )
            .fetchOne();
    System.out.println("total = " + total);



    return new PageImpl<>(content, pageable, total);
}
public long countProductsByFilter(
        String keyword,
        List<Long> categoryIds,
        List<GenderType> genders,
        List<Long> brandIds,
        List<Long> collectionIds,
        List<String> colors,
        List<String> sizes,
        Integer minPrice,
        Integer maxPrice) {

    QUser product = QUser.user;
    QUserColor productColor = QUserColor.userColor;
    QUserSize productSize = QUserSize.userSize;


    return queryFactory.select(product.id.countDistinct())
            .from(product)
            .leftJoin(product.colors, productColor)
            .leftJoin(productColor.sizes, productSize)
            .where(
                    buildKeywordPredicate(keyword, product, productColor, productSize),
                    buildCategoryPredicate(categoryIds, product),
                    buildGenderPredicate(genders, product),
                    buildBrandPredicate(brandIds, product),
                    buildCollectionPredicate(collectionIds, product),
                    buildColorPredicate(colors, productColor),
                    buildSizePredicate(sizes, productSize),
                    buildPricePredicate(minPrice, maxPrice, productSize)
            )
            .fetchOne() != null ? queryFactory.select(product.id.countDistinct())
            .from(product)
            .leftJoin(product.colors, productColor)
            .leftJoin(productColor.sizes, productSize)
            .where(
                    buildKeywordPredicate(keyword, product, productColor, productSize),
                    buildCategoryPredicate(categoryIds, product),
                    buildGenderPredicate(genders, product),
                    buildBrandPredicate(brandIds, product),
                    buildColorPredicate(colors, productColor),
                    buildSizePredicate(sizes, productSize),
                    buildPricePredicate(minPrice, maxPrice, productSize)
            )
            .fetchOne() : 0L;
}


